-- A ROWS frame around each row of a partition ordered with its NULL keys
-- first.
SELECT id, k, i32, sum(id) OVER (PARTITION BY k ORDER BY i32 ASC NULLS FIRST, id ASC NULLS LAST ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS near, first_value(id) OVER (PARTITION BY k ORDER BY i32 DESC NULLS FIRST, id ASC NULLS LAST ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS first2 FROM nulls WHERE id < 300 ORDER BY id ASC NULLS LAST
